class TFMLogicContextAndGate extends TFMLogicContextTools
{

}

Method.Source:
protected void new()
{
    super();
    inputTypes.add(TFMLogicContextTypes::Boolean);
    outputType = TFMLogicContextTypes::Boolean;
    noOfInput = 2;
}

public Object process()
{
    Object ret;


    return ret;
}

public anytype evaluate(TFMLogicContext _context)
{
    anytype         ret = true;
    SetEnumerator   sEnum;
    TFMCondition    condition;
    if (children == null)
    {
        return ret;
    }        
    sEnum = children.getEnumerator();
    while (sEnum.moveNext())
    {
        condition = sEnum.current();
        ret = ret && condition.evaluate(_context);
        if (!ret)
        {
            return ret;
        }
    }

    return ret;
}
